-- Additive website-media positions. No existing assignments, originals,
-- publication history, customers, invoices or payment records are changed.
-- Defaults remain in the website until a staff member explicitly publishes.
begin;
ALTER TABLE public.media_assets DROP CONSTRAINT IF EXISTS media_assets_category_check;
ALTER TABLE public.media_assets ADD CONSTRAINT media_assets_category_check CHECK (category IN ('end-of-tenancy','carpet','sofa-upholstery','property-services'));
ALTER TABLE public.media_assets DROP CONSTRAINT IF EXISTS media_assets_placement_check;
ALTER TABLE public.media_assets ADD CONSTRAINT media_assets_placement_check CHECK (placement IN ('main-home','gallery-end-of-tenancy','gallery-carpet','gallery-sofa','carpet-page','sofa-page','end-of-tenancy-page','gallery-property-services'));
ALTER TABLE public.media_gallery_slots DROP CONSTRAINT IF EXISTS media_gallery_slots_slot_code_check;
ALTER TABLE public.media_gallery_slots ADD CONSTRAINT media_gallery_slots_slot_code_check CHECK (slot_code ~ '^(BA0[1-5]|VIDEO0[1-4]|PHOTO(0[1-9]|1[0-9]|20)|BUILTIN_[A-Z0-9_]+)$');
ALTER TABLE public.media_website_slots ADD COLUMN IF NOT EXISTS media_kind text NOT NULL DEFAULT 'photo' CHECK (media_kind IN ('photo','video'));
INSERT INTO public.media_gallery_topics(topic_key,label,description,sort_order)
VALUES ('property-services','Other cleaning & property services','After builders, exterior cleaning, company photographs and other property services.',4)
ON CONFLICT(topic_key) DO NOTHING;

-- Frozen release catalogue; later catalogue additions need a new migration.
